"""Retain every generated byte in a verified, reviewable evidence archive."""
import argparse
import hashlib
import json
from pathlib import Path
import tarfile

ROOT=Path(__file__).resolve().parents[2]/'reports/automatic-delivery-2026-10-13'
parser=argparse.ArgumentParser(description=__doc__)
parser.add_argument('lane',choices=['before','after','warm'])
args=parser.parse_args()
folder=ROOT/('warm' if args.lane=='warm' else 'compiled/'+args.lane)
archive=ROOT/f'artifacts-{args.lane}.tar.gz'
files=sorted(p for p in folder.rglob('*') if p.is_file())
if not files:raise ValueError('no evidence files')
manifest={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in files}
with tarfile.open(archive,'w:gz',compresslevel=9) as tar:
    for p in files:
        if p.is_symlink():raise ValueError('evidence must contain ordinary files')
        tar.add(p,arcname=str(p.relative_to(ROOT)),recursive=False)
with tarfile.open(archive,'r:gz') as tar:
    actual={m.name:hashlib.sha256(tar.extractfile(m).read()).hexdigest() for m in tar.getmembers() if m.isfile()}
assert actual==manifest
(ROOT/f'archive-{args.lane}.json').write_text(json.dumps(dict(archive=archive.name,
    sha256=hashlib.sha256(archive.read_bytes()).hexdigest(),files=manifest),indent=2)+'\n')
print(len(files),'verified files;',archive.stat().st_size,'compressed bytes')
